import type { MethodKey } from './methods.ts';

export type Madhab = 'shafi' | 'hanafi';

/** Method and Asr madhab by country. A country not listed uses Muslim World League and Shafi, as Quran Tab does. */
export const COUNTRY_METHOD: Readonly<Record<string, { method: MethodKey; madhab: Madhab }>> = {
  MY: { method: 'jakim', madhab: 'shafi' },
  SG: { method: 'singapore', madhab: 'shafi' },
  ID: { method: 'kemenag', madhab: 'shafi' },
  EG: { method: 'egyptian', madhab: 'shafi' },
  TR: { method: 'turkey', madhab: 'hanafi' },
  SA: { method: 'ummAlQura', madhab: 'shafi' },
  AE: { method: 'dubai', madhab: 'shafi' },
  QA: { method: 'qatar', madhab: 'shafi' },
  KW: { method: 'kuwait', madhab: 'shafi' },
  PK: { method: 'karachi', madhab: 'hanafi' },
  IN: { method: 'karachi', madhab: 'hanafi' },
  IR: { method: 'tehran', madhab: 'shafi' },
  US: { method: 'northAmerica', madhab: 'shafi' },
  CA: { method: 'northAmerica', madhab: 'shafi' },
  GB: { method: 'northAmerica', madhab: 'shafi' },
  FR: { method: 'uoif', madhab: 'shafi' },
  MA: { method: 'morocco', madhab: 'shafi' },
  DZ: { method: 'algeria', madhab: 'shafi' },
  RU: { method: 'russia', madhab: 'shafi' },
};

export const DEFAULT_COUNTRY_METHOD: { method: MethodKey; madhab: Madhab } = { method: 'mwl', madhab: 'shafi' };

export function countryDefaults(code: string): { method: MethodKey; madhab: Madhab } {
  const hit = Object.prototype.hasOwnProperty.call(COUNTRY_METHOD, code) ? COUNTRY_METHOD[code] : undefined;
  return hit ? { ...hit } : { ...DEFAULT_COUNTRY_METHOD };
}

const BY_CODE = new Map<string, readonly string[]>();
export function isCountryCode(code: unknown): code is string {
  if (typeof code !== 'string') return false;
  if (BY_CODE.size === 0) for (const c of COUNTRIES) BY_CODE.set(c.code, c.timezones);
  return BY_CODE.has(code);
}

export function countryTimezones(code: string): readonly string[] {
  return isCountryCode(code) ? BY_CODE.get(code)! : ['UTC'];
}
